select stock_id, item_type, item_id, product_id, shop_dept_id,
       warehouse_id, current_quantity, locked_quantity,
       available_quantity, quarantine_quantity, cost_price,
       total_cost, version
from inv_stock
where stock_id = #{fact.stockId}
  and item_type = #{fact.itemType}
  and item_id = #{fact.itemId}
for update

select balance_id, item_type, item_id, product_id, warehouse_id,
       lot_id, location_id, current_quantity, locked_quantity,
       available_quantity, quarantine_quantity, cost_price,
       total_cost, version
from inv_stock_balance_detail
where balance_id = #{fact.balanceId}
  and item_type = #{fact.itemType}
  and item_id = #{fact.itemId}
  and lot_id = #{fact.lotId}
  and location_id = #{fact.locationId}
for update

mapper.update:
update inv_stock
set current_quantity = #{prepared.stock.currentAfter},
    locked_quantity = #{prepared.stock.lockedAfter},
    total_cost = #{prepared.stock.totalCostAfter},
    version = #{prepared.stock.versionAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate()
where stock_id = #{prepared.fact.stockId}
  and item_type = #{prepared.fact.itemType}
  and item_id = #{prepared.fact.itemId}
  and product_id <=> #{prepared.fact.productId}
  and version = #{prepared.stock.versionBefore}
  and current_quantity = #{prepared.stock.currentBefore}
  and available_quantity = #{prepared.stock.availableBefore}
  and locked_quantity = #{prepared.stock.lockedBefore}
  and quarantine_quantity = #{prepared.stock.quarantineBefore}
  and total_cost = #{prepared.stock.totalCostBefore}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{prepared.stock.currentAfter} = current_quantity
      - #{prepared.quantity}
  and #{prepared.stock.availableAfter} = available_quantity
  and #{prepared.stock.lockedAfter} = locked_quantity
      - #{prepared.quantity}
  and #{prepared.stock.quarantineAfter} = quarantine_quantity
  and #{prepared.stock.totalCostAfter} = total_cost
      - #{prepared.amount}
  and #{prepared.stock.versionAfter} = version + 1
  and current_quantity >= #{prepared.quantity}
  and locked_quantity >= #{prepared.quantity}
  and total_cost >= #{prepared.amount}

update inv_stock_balance_detail
set current_quantity = #{prepared.balance.currentAfter},
    locked_quantity = #{prepared.balance.lockedAfter},
    total_cost = #{prepared.balance.totalCostAfter},
    version = #{prepared.balance.versionAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate()
where balance_id = #{prepared.fact.balanceId}
  and item_type = #{prepared.fact.itemType}
  and item_id = #{prepared.fact.itemId}
  and product_id <=> #{prepared.fact.productId}
  and lot_id = #{prepared.fact.lotId}
  and location_id = #{prepared.fact.locationId}
  and version = #{prepared.balance.versionBefore}
  and current_quantity = #{prepared.balance.currentBefore}
  and available_quantity = #{prepared.balance.availableBefore}
  and available_quantity = 0
  and locked_quantity = #{prepared.balance.lockedBefore}
  and quarantine_quantity =
      #{prepared.balance.quarantineBefore}
  and cost_price = #{prepared.fact.sourceCostPrice}
  and total_cost = #{prepared.balance.totalCostBefore}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{prepared.balance.currentAfter} = current_quantity
      - #{prepared.quantity}
  and #{prepared.balance.availableAfter} = available_quantity
  and #{prepared.balance.lockedAfter} = locked_quantity
      - #{prepared.quantity}
  and #{prepared.balance.quarantineAfter} = quarantine_quantity
  and #{prepared.balance.totalCostAfter} = total_cost
      - #{prepared.amount}
  and #{prepared.balance.versionAfter} = version + 1
  and current_quantity >= #{prepared.quantity}
  and locked_quantity >= #{prepared.quantity}
  and total_cost >= #{prepared.amount}

update inv_inventory_serial
set serial_status = #{serial.physicalAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate(),
    remark = concat('adjudication return shipment=',
            #{prepared.shipmentId})
where serial_id = #{serial.serialId}
  and serial_no = #{serial.serialNo}
  and item_type = #{prepared.fact.itemType}
  and item_id = #{prepared.fact.itemId}
  and warehouse_id = #{prepared.fact.sourceWarehouseId}
  and balance_id = #{prepared.fact.balanceId}
  and lot_id = #{prepared.fact.lotId}
  and location_id = #{prepared.fact.locationId}
  and serial_status = #{serial.physicalBefore}
  and #{serial.physicalAfter} = 'shipped'

update inv_transfer_quarantine_reservation_serial
set lifecycle_status = #{serial.lifecycleAfter},
    consumption_id = #{consumptionId},
    consumed_shipment_id = #{prepared.shipmentId},
    version = #{serial.versionAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate()
where quarantine_reservation_serial_id = #{serial.bindingId}
  and quarantine_reservation_id = #{prepared.fact.reservationId}
  and receipt_serial_id = #{serial.receiptSerialId}
  and serial_id = #{serial.serialId}
  and lifecycle_status = #{serial.lifecycleBefore}
  and version = #{serial.versionBefore}
  and #{serial.lifecycleAfter} = 'CONSUMED'
  and exists (
      select 1
      from inv_transfer_quarantine_reservation_consumption event
      where event.consumption_id = #{consumptionId}
        and event.request_id = #{prepared.command.requestId}
        and event.quarantine_reservation_id =
            #{prepared.fact.reservationId}
        and event.shipment_id = #{prepared.shipmentId}
  )

update inv_transfer_quarantine_reservation
set consumed_quantity = #{prepared.consumedAfter},
    status = #{prepared.statusAfter},
    version = #{prepared.versionAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate()
where quarantine_reservation_id = #{prepared.fact.reservationId}
  and child_transfer_id = #{prepared.fact.childTransferId}
  and child_transfer_detail_id =
      #{prepared.fact.childTransferDetailId}
  and reservation_round = #{prepared.fact.reservationRound}
  and consumed_quantity = #{prepared.consumedBefore}
  and released_quantity = #{prepared.releasedQuantity}
  and reserved_quantity = #{prepared.reservedQuantity}
  and status = #{prepared.statusBefore}
  and version = #{prepared.versionBefore}
  and #{prepared.consumedAfter} = consumed_quantity
      + #{prepared.quantity}
  and #{prepared.remainingAfter} = reserved_quantity
      - #{prepared.consumedAfter} - released_quantity
  and #{prepared.versionAfter} = version + 1
  and exists (
      select 1
      from inv_transfer_quarantine_reservation_consumption event
      where event.request_id = #{prepared.command.requestId}
        and event.quarantine_reservation_id =
            #{prepared.fact.reservationId}
  )

update inv_stock
set locked_quantity = #{prepared.stock.lockedAfter},
    quarantine_quantity = #{prepared.stock.quarantineAfter},
    version = #{prepared.stock.versionAfter},
    update_by = #{prepared.command.operator},
    update_time = sysdate()
where stock_id = #{prepared.fact.stockId}
  and item_type = #{prepared.fact.itemType}
  and item_id = #{prepared.fact.itemId}
  and product_id <=> #{prepared.fact.productId}
  and version = #{prepared.stock.versionBefore}
  and current_quantity = #{prepared.stock.currentBefore}
  and available_quantity = #{prepared.stock.availableBefore}
  and locked_quantity = #{prepared.stock.lockedBefore}
  and quarantine_quantity = #{prepared.stock.quarantineBefore}
  and total_cost = #{prepared.stock.totalCostBefore}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{prepared.stock.currentAfter} = current_quantity
  and #{prepared.stock.availableAfter} = available_quantity
  and #{prepared.stock.lockedAfter} = locked_quantity
      - #{prepared.quantity}
  and #{prepared.stock.quarantineAfter} = quarantine_quantity
      + #{prepared.quantity}
  and #{prepared.stock.totalCostAfter} = total_cost
  and #{prepared.stock.versionAfter} = version + 1
  and locked_quantity >= #{prepared.quantity}

